public class Main {
    static int[][] neighbours = {
        {1, 2},    // 0
        {0, 3},    // 1
        {0, 3},    // 2
        {1, 2}     // 3
    };
    static boolean[] visited = new boolean[4];

    public static void main(String[] args) {
        dfs(0);
        System.out.println();
    }

    static void dfs(int node) {
        visited[node] = true;
        System.out.print(node + " ");
        for (int next : neighbours[node]) {
            if (!visited[next]) {
                dfs(next);
            }
        }
    }
}
